import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String S = sc.next();
        char firstChar = S.charAt(0);

        for (int i = 1; i < S.length(); i++) {
            if (S.charAt(i) != firstChar) {
                System.out.println(i + 1);
                return;
            }
        }
    }
}
